// Local pose catalog for the MVP. catalog.json is generated by scripts/pose-templates/build-templates.ts;
// images are bundled because require() needs static paths.

import type { ImageSourcePropType } from 'react-native';

import type { CueText } from '@/features/cues/phrases';
import type { CueCode } from '@/features/pose-engine/cues';
import type { MatchSettings, PoseTemplate } from '@/features/pose-engine/template';

import catalog from './catalog.json';

export interface Pose {
  slug: string;
  title: string;
  thumbnail: ImageSourcePropType;
  /** White transparent PNG drawn over the camera as the target. */
  silhouette: number;
  template: PoseTemplate;
  /** Pose-specific copy that replaces the default text of a cue. */
  cues: Partial<Record<CueCode, CueText>>;
  match: MatchSettings;
}

const images: Record<string, { thumbnail: number; silhouette: number }> = {
  'peace-sign': {
    thumbnail: require('../../../assets/poses/thumbnails/peace-sign.jpg'),
    silhouette: require('../../../assets/poses/silhouettes/peace-sign.png'),
  },
  leaning: {
    thumbnail: require('../../../assets/poses/thumbnails/leaning.jpg'),
    silhouette: require('../../../assets/poses/silhouettes/leaning.png'),
  },
  walking: {
    thumbnail: require('../../../assets/poses/thumbnails/walking.jpg'),
    silhouette: require('../../../assets/poses/silhouettes/walking.png'),
  },
  'look-back': {
    thumbnail: require('../../../assets/poses/thumbnails/look-back.jpg'),
    silhouette: require('../../../assets/poses/silhouettes/look-back.png'),
  },
  crouch: {
    thumbnail: require('../../../assets/poses/thumbnails/crouch.jpg'),
    silhouette: require('../../../assets/poses/silhouettes/crouch.png'),
  },
};

type CatalogPose = Omit<Pose, 'thumbnail' | 'silhouette'>;

export const POSES: readonly Pose[] = (catalog.poses as unknown as CatalogPose[]).map((p) => ({
  ...p,
  thumbnail: images[p.slug].thumbnail,
  silhouette: images[p.slug].silhouette,
}));

export function findPose(slug: string | undefined): Pose {
  return POSES.find((p) => p.slug === slug) ?? POSES[0];
}
